<script setup>
import {ref,computed,nextTick,onMounted,onActivated,watch} from 'vue';
import {Download,RefreshCw,ShieldCheck,Search,Check,AlertTriangle,ChevronDown} from 'lucide-vue-next';
import {useStudio,api} from '../store';
import DownloadControls from './DownloadControls.vue';
import {downloadDescription} from '../../shared/downloads.mjs';
const s=useStudio(),integrity=ref([]),checking=ref(false),repoUrl=ref(''),repo=ref(null),file=ref(''),category=ref('loras'),querying=ref(false);
const description=computed(()=>downloadDescription(s.install));
async function focusDownload(){if(s.config.settingsCategory!=='models'||!s.config.downloadFocusToken)return;await nextTick();const el=document.getElementById('active-model-download');if(el){el.scrollIntoView({block:'center',behavior:'smooth'});el.focus({preventScroll:true});}}
watch(()=>s.config.downloadFocusToken,focusDownload);onActivated(focusDownload);
const stateLabel={verified:['已校验','Verified'],missing:['缺失','Missing'],invalid:['损坏','Damaged'],unchecked:['待校验','Unchecked']};
function size(n){return n>1024**3?(n/1024**3).toFixed(2)+' GB':(n/1024**2).toFixed(1)+' MB';}
async function check(full=false){checking.value=true;await s.action(async()=>{integrity.value=await api('models/check',{full});});checking.value=false;}
async function query(){querying.value=true;await s.action(async()=>{repo.value=await api('models/hf/files',{url:repoUrl.value.trim()});file.value=repo.value.files[0]?.name||'';});querying.value=false;}
async function downloadCustom(){if(!repo.value||!file.value)return;await s.action(async()=>{await api('models/hf/download',{repo:repo.value.repo,revision:repo.value.revision,name:file.value,category:category.value});s.notify(s.t('已开始下载，完成后会自动出现在对应模型列表','Download started. The model will appear in its folder when ready.'));});}
onMounted(()=>{void check(false);void focusDownload();});watch(()=>s.install.state,state=>{if(state==='done')void check(false);});
</script>
<template><section class="download-center"><article v-if="s.install.name||s.install.state==='running'" id="active-model-download" tabindex="-1" :class="['active-model-download',{'download-highlight':s.config.downloadFocusToken}]"><div class="button-row"><Download :size="18"/><strong>{{description.title}}</strong><span class="badge">{{s.install.state==='done'?'已完成':s.install.state==='error'?'需要重试':s.install.state==='paused'?'已暂停':s.install.state==='cancelled'?'已取消':'正在下载'}}</span></div><p>{{description.purpose}}</p><code>{{s.install.name||s.install.message}}</code><div class="progress"><i :style="{width:(s.install.percent||0)+'%'}"/></div><div class="button-row"><small>{{s.install.percent||0}}% · {{size(s.install.bytes||0)}} / {{size(s.install.total||0)}}</small><small v-if="s.install.speed">{{size(s.install.speed)}}/s</small><small v-if="s.install.message">{{s.install.message}}</small></div><DownloadControls/></article><div class="download-source"><div><strong>{{s.t('下载源自动优选','Automatic download source')}}</strong><p>{{s.t('测试官方源和国内 HF-Mirror 的连通性与速度。无论使用哪一个源，均校验固定版本的 SHA256。','Tests Hugging Face and HF-Mirror, then verifies the same pinned SHA256.')}}</p></div><select v-model="s.config.downloadSource"><option value="auto">{{s.t('自动测速（推荐）','Auto (recommended)')}}</option><option value="mirror">{{s.t('国内镜像优先','China mirror first')}}</option><option value="official">{{s.t('官方源优先','Official first')}}</option></select></div>
 <div class="button-row"><button class="secondary" @click="check(true)" :disabled="checking"><ShieldCheck :size="15"/>{{checking?s.t('正在检查文件…','Checking files…'):s.t('完整校验所有模型','Verify all models')}}</button><button class="primary" :disabled="s.install.state==='running'" @click="s.action(()=>api('models/download',{profile:'all'}))"><Download :size="15"/>{{s.t('一键补全 / 修复全部模型','Download missing / repair all')}}</button><button class="secondary" :disabled="s.install.state==='running'" @click="s.action(()=>api('models/download',{profile:'finishing'}))">{{s.t('下载脸部、手部与放大模型','Download finishing models')}}</button></div><p class="muted download-hint">{{s.t('只下载缺失或损坏的文件；已有且通过校验的文件会跳过。LoRA 不会自动添加到生成配置。','Verified files are skipped. Only missing or damaged files are downloaded. LoRAs stay optional.')}}</p>
 <div v-if="integrity.length" class="integrity-table"><div v-for="item in integrity" :key="item.target" :class="{'downloading-model-row':s.install.state==='running'&&item.target.split('/').at(-1)===s.install.name}"><span :class="['integrity-dot',item.state]"/><code>{{item.target}}</code><small>{{size(item.size)}}</small><strong :class="item.state">{{s.t(...stateLabel[item.state])}}</strong></div></div>
 <details class="advanced"><summary><Download :size="16"/>{{s.t('下载其他模型 / 可选 LoRA','Download another model / optional LoRA')}}<ChevronDown :size="16"/></summary><div class="advanced-content"><p class="info-note">{{s.t('粘贴 Hugging Face 模型主页，查询后选择文件和保存目录。软件会固定仓库版本并校验 SHA256；需要登录授权的模型请手动下载后导入。','Paste a public Hugging Face model page, choose a file and folder. Downloads are pinned and SHA256 checked. Import gated models manually.')}}</p><div class="hf-search"><input v-model="repoUrl" placeholder="https://huggingface.co/组织/模型仓库" @keyup.enter="query"/><button class="secondary" @click="query" :disabled="querying||!repoUrl"><Search :size="15"/>{{querying?s.t('查询中…','Searching…'):s.t('查询模型文件','Find files')}}</button></div><div v-if="repo" class="hf-result"><label>{{s.t('模型文件','Model file')}}<select v-model="file"><option v-for="f in repo.files" :value="f.name">{{f.name}} · {{size(f.size)}}</option></select></label><label>{{s.t('保存到','Save to')}}<select v-model="category"><option value="loras">{{s.t('可选 LoRA','Optional LoRA')}}</option><option value="diffusion_models">{{s.t('生图模型','Diffusion model')}}</option><option value="controlnet">{{s.t('重绘 ControlNet','Inpaint ControlNet')}}</option><option value="text_encoders">{{s.t('文本编码器','Text encoder')}}</option><option value="vae">VAE</option><option value="upscale_models">{{s.t('放大模型','Upscale model')}}</option><option value="detectors">{{s.t('检测模型','Detector')}}</option></select></label><button class="primary" @click="downloadCustom" :disabled="!file||s.install.state==='running'"><Download :size="15"/>{{s.t('下载并校验','Download & verify')}}</button></div><p v-if="repo&&!repo.files.length" class="info-note">{{s.t('没有找到带 SHA256 的可下载权重。请确认仓库或导入本地文件。','No downloadable weights with SHA256 found. Check the repository or import a local file.')}}</p></div></details>
</section></template>
